(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-584":{scenario:{company:"Đông Hải Steel Rolling",supervisor:{name:"Hoàng Văn Thịnh",role:{vi:"Trưởng phòng Cơ điện",en:"Electrical Engineering Manager"}},ref_code:"PFC-2209",title:{vi:"Bù đúng công suất. Chống cộng hưởng. Không đóng điện vội.",en:"Right compensation. No resonance. No rushed energising."},brief:{vi:"Thanh cái MSB-2 (400 V) cấp cho dây chuyền cán có nhiều biến tần 6 xung. Công suất tác dụng lớn nhất 1500 kW, hệ số công suất 0.80, mục tiêu thiết kế 0.95. Hồ sơ thiết kế tụ bù nháp PFC-2209 chọn sai kiểu tủ bù và dung lượng. Đối chiếu với kết quả đo sóng hài và cơ sở thiết kế đã duyệt, sửa kiểu tủ bù và dung lượng bù yêu cầu (kvar, làm tròn số nguyên), rồi lập báo cáo có căn cứ.",en:"Busbar MSB-2 (400 V) feeds a rolling line with many 6-pulse drives. Peak active power is 1500 kW at power factor 0.80, design target 0.95. Draft capacitor bank design PFC-2209 picks the wrong bank type and rating. Check it against the approved harmonic survey and design basis, correct the bank type and the required compensation (kvar, nearest integer), then write an evidence-based report."},reference_title:{vi:"Cơ sở thiết kế bù công suất phản kháng đã duyệt · PFC-2209",en:"Approved reactive power compensation design basis · PFC-2209"},fields:[{id:"PFC_TYPE",label:{vi:"Kiểu tủ tụ bù",en:"Capacitor bank type"},initial:"STANDARD",expected:"DETUNED-7%",choices:["STANDARD","DETUNED-7%","DETUNED-14%"],reference:"Biên bản đo sóng hài MSB-2",hint:{vi:"Lưới nhiều hài bậc 5, 7 dễ cộng hưởng với tụ thường; chọn mức kháng theo bậc hài thấp nhất đáng kể.",en:"A grid rich in 5th and 7th harmonics can resonate with plain capacitors; pick the reactor tuning by the lowest significant harmonic."}},{id:"QC_KVAR",label:{vi:"Dung lượng bù yêu cầu (kvar)",en:"Required compensation (kvar)"},initial:"790",expected:"632",reference:"Cơ sở thiết kế MSB-2",ref_value:{vi:"P lớn nhất 1500 kW; cos φ1 0.80 (tan φ1 = 0.7500); cos φ2 mục tiêu 0.95 (tan φ2 = 0.3287)",en:"Peak P 1500 kW; PF1 0.80 (tan φ1 = 0.7500); target PF2 0.95 (tan φ2 = 0.3287)"},hint:{vi:"Công thức bù dùng công suất tác dụng kW, không dùng công suất biểu kiến kVA.",en:"The compensation formula uses active power in kW, not apparent power in kVA."}}],sop32:{vi:"Qc = P x (tan φ1 - tan φ2), với P là công suất tác dụng (kW), φ1, φ2 ứng với hệ số công suất hiện tại và mục tiêu; làm tròn số nguyên kvar. Tủ kháng 7% (khoảng 189 Hz) khi hài bậc 5 trội và không có hài bậc 3 đáng kể.",en:"Qc = P x (tan φ1 - tan φ2), with P the active power (kW) and φ1, φ2 for present and target power factor; round to whole kvar. Use a 7% detuned bank (about 189 Hz) when the 5th harmonic dominates and the 3rd is insignificant."},context:{label:"POWER QUALITY / PFC-2209",metrics:[{label:{vi:"Công suất tác dụng",en:"Active power"},value:"1500 kW"},{label:{vi:"Hệ số công suất",en:"Power factor"},value:"0.80 / 0.95"},{label:{vi:"Méo điện áp THDv",en:"Voltage THDv"},value:"6.8%"}]},terminal:{system:"pq-analyzer",settable:["PFC_TYPE","QC_KVAR"],commands:[{cmd:"status",out:{vi:"MSB-2 400 V: P = 1500 kW, S = 1875 kVA, cos φ = 0.80; hồ sơ nháp PFC_TYPE=STANDARD, QC_KVAR=790",en:"MSB-2 400 V: P = 1500 kW, S = 1875 kVA, power factor 0.80; draft PFC_TYPE=STANDARD, QC_KVAR=790"}},{cmd:"harmonics msb2",out:{vi:"THDv 6.8%; H5 5.1%, H7 3.4%, H11 1.6%, H3 0.4%; nguồn hài chủ yếu là biến tần chỉnh lưu 6 xung",en:"THDv 6.8%; H5 5.1%, H7 3.4%, H11 1.6%, H3 0.4%; harmonics mainly from 6-pulse rectifier drives"}},{cmd:"cat design_basis.txt",out:{vi:"Mục tiêu cos φ 0.95 tại tải lớn nhất 1500 kW; ngưỡng hợp đồng mua bán điện mô phỏng 0.90",en:"Target power factor 0.95 at peak load 1500 kW; training power purchase contract threshold 0.90"}},{cmd:"cat bank_catalog.txt",out:{vi:"Tủ thường: không kháng; tủ kháng 7%: cộng hưởng khoảng 189 Hz, dùng khi hài bậc 5 trội; tủ kháng 14%: khoảng 134 Hz, dùng khi có hài bậc 3 đáng kể",en:"Standard bank: no reactor; 7% detuned: resonance about 189 Hz, for dominant 5th harmonic; 14% detuned: about 134 Hz, for significant 3rd harmonic"}},{cmd:"cat draft_pfc.txt",out:{vi:"Bản nháp: Qc = 1875 x (0.7500 - 0.3287), chọn tủ thường không kháng để tiết kiệm chi phí",en:"Draft: Qc = 1875 x (0.7500 - 0.3287), standard unreactored bank chosen to save cost"}}]},crisis:{vi:"Nhà thầu lắp đặt nhắn: “Tủ bù lắp xong rồi, đóng điện thử luôn tối nay cho kịp nghiệm thu. Biên bản thí nghiệm và phiếu thao tác bọn em ký bổ sung sau.”",en:"The installation contractor messages: “The bank is installed, let us energise it tonight to make acceptance. We will sign the test reports and switching order afterwards.”"},options:{safe:{vi:"Từ chối đóng điện khi chưa có biên bản thí nghiệm đạt, phiếu thao tác và người giám sát; báo trưởng phòng cơ điện, sửa thiết kế sang tủ kháng 7% trước nghiệm thu.",en:"Refuse to energise without passed test reports, a switching order and a supervisor; inform the electrical manager and revise the design to a 7% detuned bank before acceptance."},shortcut:{vi:"Cho đóng điện thử tối nay, giấy tờ thí nghiệm hoàn thiện sau.",en:"Allow energising tonight and complete the test paperwork later."},wait:{vi:"Không trả lời và để nhà thầu tự quyết định thời điểm đóng điện.",en:"Do not reply and let the contractor decide when to energise."}},questions:{vi:["Vì sao dung lượng bù đúng là 632 kvar và cần tủ kháng 7%? Nếu dùng tụ thường trên lưới này điều gì có thể xảy ra?","Những điều kiện nào phải có trước khi đóng điện một tủ tụ bù mới, và bạn xử lý áp lực của nhà thầu ra sao?"],en:["Why is the correct compensation 632 kvar with a 7% detuned bank? What could happen with plain capacitors on this grid?","Which conditions must be met before energising a new capacitor bank, and how do you handle the contractor's pressure?"]},hints:{vi:["Đặt hồ sơ nháp cạnh biên bản đo sóng hài và đọc bậc hài nào trội.","Áp dụng SOP mục 3.2: tính tan φ từ cos φ và nhân với công suất tác dụng, không phải công suất biểu kiến.","Đọc lại SOP mục 4.2: không đóng điện khi chưa có kết quả thí nghiệm và phiếu thao tác được duyệt."],en:["Place the draft next to the harmonic survey and read which harmonic dominates.","Apply SOP 3.2: derive tan φ from the power factor and multiply by active power, not apparent power.","Re-read SOP 4.2: never energise before test results and an approved switching order exist."]}},learning:{summary:{vi:"Kỹ sư Hệ thống Điện Công nghiệp và Trạm biến áp thiết kế, vận hành và bảo vệ hệ thống cung cấp điện của nhà máy: trạm biến áp trung thế, tủ phân phối hạ thế, bảo vệ rơ le, nối đất, bù công suất phản kháng và chất lượng điện năng. Mục tiêu là cấp điện liên tục, an toàn cho người và thiết bị với chi phí năng lượng hợp lý. Công việc đòi hỏi vững tính toán ngắn mạch, phối hợp bảo vệ và kỷ luật an toàn điện tuyệt đối.",en:"An Electrical Power Systems Engineer designs, operates and protects a plant's power supply: medium-voltage substations, low-voltage switchboards, relay protection, earthing, reactive power compensation and power quality. The goal is continuous, safe power for people and equipment at a reasonable energy cost. The role requires solid short-circuit and protection coordination skills and absolute electrical safety discipline."},responsibilities:{vi:["Tính toán phụ tải, ngắn mạch và chọn máy biến áp, cáp, thiết bị đóng cắt.","Lập và kiểm tra trị số chỉnh định rơ le, phối hợp bảo vệ giữa các cấp.","Đo và cải thiện chất lượng điện năng: hệ số công suất, sóng hài, sụt áp.","Lập phiếu thao tác, giám sát thí nghiệm, nghiệm thu và đóng điện thiết bị mới.","Lập kế hoạch bảo trì trạm biến áp, đo nhiệt hồng ngoại và phân tích sự cố mất điện."],en:["Calculate loads and short circuits and size transformers, cables and switchgear.","Prepare and check relay settings and coordinate protection between levels.","Measure and improve power quality: power factor, harmonics and voltage drop.","Issue switching orders and supervise testing, acceptance and energising of new equipment.","Plan substation maintenance, run infrared surveys and analyse outages."]},competencies:[{name:{vi:"Tính toán hệ thống điện",en:"Power system calculation"},desc:{vi:"Tính dòng ngắn mạch, sụt áp, trào lưu công suất và chọn thiết bị đúng khả năng cắt.",en:"Compute short-circuit currents, voltage drop and load flow and size equipment by breaking capacity."}},{name:{vi:"Bảo vệ rơ le",en:"Protection relaying"},desc:{vi:"Chỉnh định quá dòng, chạm đất, so lệch và lập đồ thị phối hợp chọn lọc.",en:"Set overcurrent, earth fault and differential protection and build selectivity curves."}},{name:{vi:"Chất lượng điện năng",en:"Power quality"},desc:{vi:"Đo, phân tích sóng hài, thiết kế bù có kháng và lọc sóng hài.",en:"Measure and analyse harmonics and design detuned compensation and filters."}},{name:{vi:"Vận hành và thao tác",en:"Operation and switching"},desc:{vi:"Lập phiếu thao tác, cô lập, nối đất an toàn và giám sát đóng điện.",en:"Write switching orders, isolate, earth safely and supervise energising."}},{name:{vi:"Kỷ luật an toàn điện",en:"Electrical safety discipline"},desc:{vi:"Không đóng điện khi thiếu thí nghiệm, phiếu thao tác, và dám dừng việc khi nguy hiểm.",en:"Never energise without tests and switching orders, and stop work when it is dangerous."}}],knowledge:{vi:["IEC 60909 về tính toán dòng ngắn mạch trong hệ thống điện xoay chiều ba pha.","IEC 60255 về rơ le bảo vệ, gồm các đặc tính thời gian phụ thuộc.","IEC 61850 về truyền thông trong trạm biến áp tự động hóa.","IEEE 519 về giới hạn sóng hài trong hệ thống điện.","IEC 61439 về tủ điện hạ thế và quy chuẩn kỹ thuật quốc gia hiện hành về kỹ thuật điện, an toàn điện."],en:["IEC 60909 on short-circuit current calculation in three-phase AC systems.","IEC 60255 on protection relays, including inverse-time characteristics.","IEC 61850 on communication in substation automation.","IEEE 519 on harmonic limits in electric power systems.","IEC 61439 on low-voltage switchgear assemblies and current national technical regulations on electrical engineering and safety."]},tools:["Phần mềm tính toán hệ thống điện","Máy phân tích chất lượng điện năng","Bộ thí nghiệm rơ le nhất thứ, nhị thứ","Camera nhiệt hồng ngoại","Máy đo điện trở nối đất"],kpis:{vi:["Số giờ mất điện ngoài kế hoạch trên năm.","Hệ số công suất trung bình tháng so với mục tiêu.","Tỷ lệ sự cố được rơ le cắt chọn lọc đúng cấp.","Số vi phạm quy trình thao tác (mục tiêu bằng 0)."],en:["Unplanned outage hours per year.","Monthly average power factor versus target.","Share of faults cleared selectively at the right level.","Switching procedure violations (target zero)."]},day:[{time:"07:30",vi:"Đọc nhật ký vận hành trạm, kiểm tra các lần rơ le tác động trong đêm.",en:"Read the substation log and check overnight relay operations."},{time:"09:00",vi:"Đo sóng hài và hệ số công suất tại các thanh cái cấp cho biến tần.",en:"Measure harmonics and power factor on busbars feeding drives."},{time:"11:00",vi:"Kiểm tra trị số chỉnh định rơ le xuất tuyến mới và đồ thị phối hợp.",en:"Check relay settings for a new feeder and the coordination curves."},{time:"14:00",vi:"Giám sát thí nghiệm tủ tụ bù, ký biên bản khi các hạng mục đạt.",en:"Supervise capacitor bank tests and sign reports when all items pass."},{time:"16:30",vi:"Lập phiếu thao tác cho đợt cắt điện bảo trì cuối tuần và họp an toàn.",en:"Write switching orders for the weekend maintenance outage and hold a safety briefing."}],mistakes:{vi:["Tính dung lượng bù theo kVA thay vì kW, dẫn tới bù thừa và quá áp khi non tải.","Lắp tụ bù thường trên lưới nhiều sóng hài, gây cộng hưởng, nổ tụ, nhảy áp tô mát.","Đóng điện thiết bị mới khi chưa có biên bản thí nghiệm và phiếu thao tác."],en:["Sizing compensation on kVA instead of kW, causing overcompensation and light-load overvoltage.","Installing plain capacitors on a harmonic-rich grid, causing resonance, capacitor failures and breaker trips.","Energising new equipment without test reports and a switching order."]},career:[{vi:"Kỹ thuật viên vận hành trạm",en:"Substation operator"},{vi:"Kỹ sư hệ thống điện nhà máy",en:"Plant power systems engineer"},{vi:"Kỹ sư trưởng bảo vệ và chất lượng điện",en:"Lead protection and power quality engineer"},{vi:"Trưởng phòng năng lượng và cơ điện",en:"Head of energy and electrical engineering"}],glossary:[{term:"Detuned reactor",vi:"Cuộn kháng nối tiếp với tụ để dời tần số cộng hưởng xuống dưới bậc hài thấp nhất đáng kể.",en:"Series reactor with a capacitor that moves resonance below the lowest significant harmonic."},{term:"THD",vi:"Tổng độ méo sóng hài, tỷ lệ giữa tổng các thành phần hài và thành phần cơ bản.",en:"Total harmonic distortion, the ratio of combined harmonic content to the fundamental."},{term:"Power factor",vi:"Hệ số công suất, tỷ số giữa công suất tác dụng và công suất biểu kiến.",en:"The ratio of active power to apparent power."},{term:"Selectivity",vi:"Tính chọn lọc, chỉ thiết bị bảo vệ gần điểm sự cố nhất được cắt.",en:"Only the protective device closest to the fault trips."},{term:"Switching order",vi:"Phiếu thao tác, trình tự đóng cắt được duyệt trước để vận hành an toàn.",en:"Pre-approved switching sequence for safe operation."}],quiz:[{q:{vi:"P = 1000 kW, cos φ từ 0.80 (tan 0.75) lên mức có tan φ = 0.33. Cần bù bao nhiêu kvar?",en:"P = 1000 kW, power factor from 0.80 (tan 0.75) to a level with tan φ = 0.33. How much kvar is needed?"},options:{vi:["420 kvar","525 kvar","750 kvar","330 kvar"],en:["420 kvar","525 kvar","750 kvar","330 kvar"]},answer:0,explain:{vi:"Qc = 1000 x (0.75 - 0.33) = 420 kvar; tính theo kVA 1250 sẽ ra sai 525 kvar.",en:"Qc = 1000 x (0.75 - 0.33) = 420 kvar; using 1250 kVA gives the wrong 525 kvar."}},{q:{vi:"Tủ tụ bù kháng 7% trên lưới 50 Hz có tần số cộng hưởng khoảng bao nhiêu?",en:"What is the approximate resonant frequency of a 7% detuned bank on a 50 Hz grid?"},options:{vi:["134 Hz","250 Hz","350 Hz","189 Hz"],en:["134 Hz","250 Hz","350 Hz","189 Hz"]},answer:3,explain:{vi:"f = 50 / căn bậc hai của 0.07, xấp xỉ 189 Hz, dưới hài bậc 5 (250 Hz).",en:"f = 50 / square root of 0.07, about 189 Hz, below the 5th harmonic (250 Hz)."}},{q:{vi:"Nhà thầu muốn đóng điện tủ mới trước, ký biên bản thí nghiệm sau. Bạn làm gì?",en:"A contractor wants to energise a new panel now and sign the test report later. What do you do?"},options:{vi:["Đồng ý vì đã lắp xong","Cho đóng điện nhưng đứng xa","Từ chối đến khi có biên bản đạt, phiếu thao tác và báo trưởng phòng","Để nhà thầu tự chịu trách nhiệm"],en:["Agree since installation is done","Allow it but stand back","Refuse until passed tests and a switching order exist and inform the manager","Let the contractor take responsibility"]},answer:2,explain:{vi:"Thiết bị chưa thí nghiệm có thể hỏng cách điện, gây hồ quang nguy hiểm tính mạng.",en:"Untested equipment may have insulation faults and cause life-threatening arc flash."}},{q:{vi:"Tiêu chuẩn nào hướng dẫn tính toán dòng ngắn mạch trong hệ thống xoay chiều ba pha?",en:"Which standard guides short-circuit calculation in three-phase AC systems?"},options:{vi:["IEC 61850","IEC 60909","IEC 61131-3","IEEE 519"],en:["IEC 61850","IEC 60909","IEC 61131-3","IEEE 519"]},answer:1,explain:{vi:"IEC 60909 là chuẩn quốc tế về tính toán dòng ngắn mạch trong lưới xoay chiều ba pha.",en:"IEC 60909 is the international standard for short-circuit calculation in three-phase AC networks."}}],tools_en:["Power system analysis software","Power quality analyzer","Primary & secondary injection relay test sets","Infrared thermal camera","Earth resistance tester"]}}})})(window.KKR);
